  document.addEventListener('keydown',event=>{
    if(event.isComposing)return;
    if((event.metaKey||event.ctrlKey)&&!event.altKey&&event.key.toLowerCase()==='k'){
      if(document.querySelector('.dialog'))return;
      event.preventDefault();openModuleFinder();return;
    }
    if(!document.querySelector('#module-finder'))return;
    const controls=[...document.querySelectorAll('[data-module-target]')],index=controls.indexOf(document.activeElement),fromQuery=event.target.id==='module-query';
    if((fromQuery||index>=0)&&['ArrowDown','ArrowUp'].includes(event.key)){
      event.preventDefault();if(!controls.length)return;
      const next=fromQuery?(event.key==='ArrowDown'?0:controls.length-1):(index+(event.key==='ArrowDown'?1:-1)+controls.length)%controls.length;
      controls[next].focus();controls[next].scrollIntoView({block:'nearest'});return;
    }
    if(index>=0&&['Home','End'].includes(event.key)){event.preventDefault();controls[event.key==='Home'?0:controls.length-1]?.focus();return}
    if(fromQuery&&event.key==='Enter'){event.preventDefault();controls[0]?.click()}
  });
